#ifndef EPIC_SWITCH_CTX_H
#define EPIC_SWITCH_CTX_H

#include <stdbool.h>
#include <stdint.h>
#include "epic_clean.h"
#include "sha256.h"

#define EPIC_TRACE_MAX 32

typedef struct {
    int rank;
    size_t len;
    uint8_t frame[EPIC_MAX_FRAME];
} epic_trace_rec_t;

typedef struct {
    int kind;                 /* epic_primitive_t */
    int mode;                 /* 2 or 3 */
    int root;
    uint32_t K, D, N, start;
    uint32_t m;               /* K/4 for reducescatter */
    uint8_t req_mask;         /* sources a slot needs before it is complete */
    uint32_t outc[EPIC_STAR4_HOSTS];   /* output space size per receiver */
    size_t stride;            /* retained payload bytes per slot */

    uint8_t *used;            /* slot allocated */
    uint32_t *slot_p;         /* slot logical p identity */
    uint8_t *slot_mask;       /* accepted source mask */
    uint8_t *pool;            /* N * stride retained bytes */

    uint32_t retired;         /* b */
    uint64_t occupied;
    uint32_t R[EPIC_STAR4_HOSTS];
    uint32_t sent[EPIC_STAR4_HOSTS];
    uint32_t down[EPIC_STAR4_HOSTS];
    uint32_t up[EPIC_STAR4_HOSTS];
    uint8_t repeat[EPIC_STAR4_HOSTS];

    uint64_t c_data, c_ack, c_tx_data, c_tx_ack, c_accept, c_dup, c_block,
        c_stale, c_wire, c_endpoint, c_ignore, c_fail, c_overwrite;

    int64_t budget;
    epic_sha256_t sha;
    uint64_t packets, bytes;
    uint32_t trace_limit, trace_n;
    epic_trace_rec_t *trace;
    uint8_t scratch[EPIC_MAX_PAYLOAD_BYTES];
    uint8_t frame[EPIC_MAX_FRAME];
} epic_ctx_t;

/* Shared collector internals (star4_switch.c). */
void epic_init_outc(epic_ctx_t *ctx);
int epic_slot_index(const epic_ctx_t *ctx, uint32_t p, uint32_t *idx);
uint8_t *epic_slot_base(const epic_ctx_t *ctx, uint32_t index);
void epic_service(epic_ctx_t *ctx, int retry_rank);
void collector_ingress(epic_ctx_t *ctx, int rank, const uint8_t *frame,
                       size_t length);

#endif
/* Offline replay ABI: context lifetime, certificates, transcript and trace. */
#include "switch_ctx.h"

#include <stdlib.h>
#include <string.h>

#include "offline_api.h"

void collector_ingress(epic_ctx_t *ctx, int rank, const uint8_t *frame,
                       size_t length);

static void *xalloc(size_t n) { return calloc(n ? n : 1, 1); }

void *epic_open(int primitive, int mode, int root, uint32_t count, uint32_t words,
                uint32_t capacity, uint32_t start, uint32_t trace_limit) {
    epic_ctx_t *ctx = xalloc(sizeof(*ctx));
    if (!ctx) {
        return NULL;
    }
    ctx->kind = primitive;
    ctx->mode = mode;
    ctx->root = root;
    ctx->K = count;
    ctx->D = words;
    ctx->N = capacity;
    ctx->start = start & 0x00ffffffu;
    ctx->m = count / 4;
    ctx->req_mask = (primitive == (int)EPIC_PRIM_BCAST)
                        ? (uint8_t)(1u << (unsigned)root)
                        : (uint8_t)0xfu;
    size_t stride;
    if (primitive == (int)EPIC_PRIM_ALLGATHER) {
        stride = 16 * (size_t)words;
    } else if (primitive == (int)EPIC_PRIM_BARRIER) {
        stride = 0;
    } else {
        stride = 4 * (size_t)words;
    }
    ctx->stride = stride;
    ctx->used = xalloc(capacity);
